<?php
declare(strict_types=1);
require_once __DIR__ . '/functions.php';
$admin=require_admin();$pdo=db();$pageTitle='Административная панель';$active='admin';
$tables=[
 'users'=>['label'=>'Пользователи','pk'=>'id','fields'=>['name','phone','email','role']],
 'programs'=>['label'=>'Программы','pk'=>'id','fields'=>['name','slug','summary','description','age_group','duration_minutes','heroes_count','price','accent','is_active']],
 'animators'=>['label'=>'Аниматоры','pk'=>'id','fields'=>['name','character_name','bio','experience_years','rating','accent','photo_path','is_active']],
 'program_animators'=>['label'=>'Программы и аниматоры','pk'=>null,'fields'=>['program_id','animator_id']],
 'orders'=>['label'=>'Заказы','pk'=>'id','fields'=>['user_id','program_id','animator_id','customer_name','phone','email','event_date','event_time','address','children_age','children_count','comment','total_price','status']],
 'reviews'=>['label'=>'Отзывы','pk'=>'id','fields'=>['user_id','order_id','rating','title','body','event_date','is_published']],
 'photos'=>['label'=>'Фотографии','pk'=>'id','fields'=>['user_id','order_id','file_name','original_name','mime_type']],
];
$views=['v_program_catalog','v_animator_programs','v_upcoming_orders','v_customer_order_history','v_program_ratings'];
$section=(string)($_GET['table']??'users');if(!isset($tables[$section])&&!in_array($section,$views,true))$section='users';
if(is_post()&&$pdo){verify_csrf();$table=(string)($_POST['table']??'');if(!isset($tables[$table]))exit('Недопустимая таблица.');$config=$tables[$table];$action=(string)($_POST['action']??'');$id=(int)($_POST['id']??0);
 if($action==='delete'){$where=$config['pk']?$config['pk'].'=?':'program_id=? AND animator_id=?';$values=$config['pk']?[$id]:[(int)$_POST['program_id'],(int)$_POST['animator_id']];$s=$pdo->prepare("DELETE FROM `$table` WHERE $where");$s->execute($values);flash('success','Запись удалена.');redirect('admin.php?table='.$table);}
 $values=[];$fields=[];foreach($config['fields'] as $field){if($table==='users'&&$field==='email'&&empty($_POST[$field]))continue;$fields[]=$field;$values[]=trim((string)($_POST[$field]??''))===''?null:$_POST[$field];}
 if($action==='save'&&$table==='program_animators'&&isset($_POST['original_program_id'],$_POST['original_animator_id'])){$parts=array_map(fn($f)=>"`$f`=?",$fields);$values[]=(int)$_POST['original_program_id'];$values[]=(int)$_POST['original_animator_id'];$s=$pdo->prepare("UPDATE `program_animators` SET ".implode(',',$parts)." WHERE program_id=? AND animator_id=?");$s->execute($values);flash('success','Запись изменена.');}
 elseif($action==='save'&&$id&&$config['pk']){$parts=array_map(fn($f)=>"`$f`=?",$fields);$values[]=$id;$s=$pdo->prepare("UPDATE `$table` SET ".implode(',',$parts)." WHERE `{$config['pk']}`=?");$s->execute($values);flash('success','Запись изменена.');}
 else{$columns=implode(',',array_map(fn($f)=>"`$f`",$fields));$marks=implode(',',array_fill(0,count($fields),'?'));$s=$pdo->prepare("INSERT INTO `$table` ($columns) VALUES ($marks)");$s->execute($values);flash('success','Запись добавлена.');}redirect('admin.php?table='.$table);
}
$rows=[];$columns=[];$editing=null;
if($pdo){$rows=$pdo->query("SELECT * FROM `$section` LIMIT 100")->fetchAll();if($rows)$columns=array_keys($rows[0]);elseif(isset($tables[$section]))$columns=array_merge($tables[$section]['pk']?[$tables[$section]['pk']]:[],$tables[$section]['fields']);if(isset($_GET['edit'])&&isset($tables[$section])&&$tables[$section]['pk']){$s=$pdo->prepare("SELECT * FROM `$section` WHERE `{$tables[$section]['pk']}`=?");$s->execute([(int)$_GET['edit']]);$editing=$s->fetch();}elseif($section==='program_animators'&&isset($_GET['program_id'],$_GET['animator_id'])){$s=$pdo->prepare('SELECT * FROM program_animators WHERE program_id=? AND animator_id=?');$s->execute([(int)$_GET['program_id'],(int)$_GET['animator_id']]);$editing=$s->fetch();}}
require __DIR__ . '/partials/header.php';
?>
<section class="section"><div class="container"><span class="eyebrow">Управление базой данных</span><h1 class="section-title">АДМИНИСТРАТИВНАЯ ПАНЕЛЬ</h1><?php if(!$pdo): ?><div class="alert alert--error">Нет подключения к MySQL. Импортируйте database/schema.sql и проверьте config.php.</div><?php endif; ?><div class="admin-layout" style="margin-top:28px"><nav class="panel admin-nav"><b>Таблицы</b><?php foreach($tables as $name=>$config): ?><a class="<?= $section===$name?'is-active':'' ?>" href="admin.php?table=<?= e($name) ?>"><?= e($config['label']) ?></a><?php endforeach; ?><b style="margin-top:12px">Представления</b><?php foreach($views as $name): ?><a class="<?= $section===$name?'is-active':'' ?>" href="admin.php?table=<?= e($name) ?>"><?= e($name) ?></a><?php endforeach; ?></nav><div><div class="panel"><h2><?= e($tables[$section]['label']??$section) ?></h2><?php if(isset($tables[$section])&&$pdo): ?><form method="post"><h3><?= $editing?'Изменить запись':'Добавить запись' ?></h3><?= csrf_field() ?><input type="hidden" name="table" value="<?= e($section) ?>"><input type="hidden" name="action" value="save"><?php if($editing&&$tables[$section]['pk']): ?><input type="hidden" name="id" value="<?= (int)$editing[$tables[$section]['pk']] ?>"><?php elseif($editing): ?><input type="hidden" name="original_program_id" value="<?= (int)$editing['program_id'] ?>"><input type="hidden" name="original_animator_id" value="<?= (int)$editing['animator_id'] ?>"><?php endif; ?><div class="form-grid"><?php foreach($tables[$section]['fields'] as $field): ?><div class="field"><label><?= e($field) ?></label><input name="<?= e($field) ?>" value="<?= e((string)($editing[$field]??'')) ?>" <?= in_array($field,['name','email','program_id','animator_id','customer_name'],true)?'required':'' ?>></div><?php endforeach; ?></div><div class="form-actions"><button class="button button--small"><?= $editing?'Сохранить':'Добавить' ?></button></div></form><?php endif; ?></div><div class="table-wrap" style="margin-top:20px"><table class="data-table"><thead><tr><?php foreach($columns as $column): ?><th><?= e($column) ?></th><?php endforeach; ?><?php if(isset($tables[$section])): ?><th>Действия</th><?php endif; ?></tr></thead><tbody><?php foreach($rows as $row): ?><tr><?php foreach($columns as $column): ?><td><?= e(mb_strimwidth((string)($row[$column]??''),0,80,'…')) ?></td><?php endforeach; ?><?php if(isset($tables[$section])): ?><td><div class="actions"><?php if($tables[$section]['pk']): ?><a class="button button--small" href="admin.php?table=<?= e($section) ?>&edit=<?= (int)$row[$tables[$section]['pk']] ?>">Изменить</a><?php else: ?><a class="button button--small" href="admin.php?table=program_animators&program_id=<?= (int)$row['program_id'] ?>&animator_id=<?= (int)$row['animator_id'] ?>">Изменить</a><?php endif; ?><form method="post"><?= csrf_field() ?><input type="hidden" name="table" value="<?= e($section) ?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?= (int)($row[$tables[$section]['pk']]??0) ?>"><?php if(!$tables[$section]['pk']): ?><input type="hidden" name="program_id" value="<?= (int)$row['program_id'] ?>"><input type="hidden" name="animator_id" value="<?= (int)$row['animator_id'] ?>"><?php endif; ?><button class="button button--danger" data-confirm="Удалить запись?">Удалить</button></form></div></td><?php endif; ?></tr><?php endforeach; ?></tbody></table></div></div></div></div></section>
<?php require __DIR__ . '/partials/footer.php'; ?>
